import crypto from 'crypto';
import { Redis } from 'ioredis';

interface AuthConfig {
  maxAttempts: number;
  windowMs: number;
  lockoutMs: number;
  hashIterations: number;
  keyLength: number;
  saltLength: number;
}

const config: AuthConfig = {
  maxAttempts: 5,
  windowMs: 900000,
  lockoutMs: 1800000,
  hashIterations: 100000,
  keyLength: 64,
  saltLength: 32
};

const redis = new Redis({
  host: process.env.REDIS_HOST || 'redis-cluster.auth-system.svc.cluster.local',
  port: 6379,
  password: process.env.REDIS_PASSWORD,
  tls: { rejectUnauthorized: true }
});

async function deriveKey(password: string, salt: Buffer): Promise<Buffer> {
  return new Promise((resolve, reject) => {
    crypto.pbkdf2(password, salt, config.hashIterations, config.keyLength, 'sha512', (err, key) => {
      if (err) reject(err);
      else resolve(key);
    });
  });
}

async function getRateLimitState(identifier: string): Promise<{ attempts: number; firstAttempt: number; locked: boolean }> {
  const key = `auth:ratelimit:${identifier}`;
  const data = await redis.hgetall(key);

  if (!data || !data.attempts) {
    return { attempts: 0, firstAttempt: 0, locked: false };
  }

  const attempts = parseInt(data.attempts, 10);
  const firstAttempt = parseInt(data.firstAttempt, 10);
  const lockedUntil = parseInt(data.lockedUntil || '0', 10);

  const now = Date.now();

  if (lockedUntil > now) {
    return { attempts, firstAttempt, locked: true };
  }

  if (now - firstAttempt > config.windowMs) {
    await redis.del(key);
    return { attempts: 0, firstAttempt: 0, locked: false };
  }

  return { attempts, firstAttempt, locked: false };
}

async function recordFailedAttempt(identifier: string): Promise<void> {
  const key = `auth:ratelimit:${identifier}`;
  const now = Date.now();

  const exists = await redis.exists(key);

  if (!exists) {
    await redis.hset(key, 'attempts', '1', 'firstAttempt', now.toString());
    await redis.pexpire(key, config.windowMs);
  } else {
    const newAttempts = await redis.hincrby(key, 'attempts', 1);
    if (newAttempts >= config.maxAttempts) {
      await redis.hset(key, 'lockedUntil', (now + config.lockoutMs).toString());
      await redis.pexpire(key, config.lockoutMs);
    }
  }
}

async function constantTimeCompare(a: Buffer, b: Buffer): Promise<boolean> {
  if (a.length !== b.length) {
    const dummy = Buffer.alloc(b.length);
    crypto.timingSafeEqual(dummy, b);
    return false;
  }
  return crypto.timingSafeEqual(a, b);
}

export async function authenticateUser(
  username: string,
  password: string,
  clientIp: string
): Promise<{ success: boolean; error?: string }> {
  const compositeIdentifier = `${clientIp}:${username}`;

  const rateLimitState = await getRateLimitState(compositeIdentifier);

  if (rateLimitState.locked) {
    return { success: false, error: 'Account temporarily locked. Try again later.' };
  }

  const userRecord = await redis.hgetall(`user:${username}`);

  if (!userRecord || !userRecord.passwordHash) {
    const fakeSalt = crypto.randomBytes(config.saltLength);
    await deriveKey(password, fakeSalt);
    await recordFailedAttempt(compositeIdentifier);
    return { success: false, error: 'Invalid credentials' };
  }

  const storedHash = Buffer.from(userRecord.passwordHash, 'hex');
  const salt = Buffer.from(userRecord.salt, 'hex');

  const derivedKey = await deriveKey(password, salt);
  const isValid = await constantTimeCompare(derivedKey, storedHash);

  if (!isValid) {
    await recordFailedAttempt(compositeIdentifier);
    return { success: false, error: 'Invalid credentials' };
  }

  const ipOnlyState = await getRateLimitState(clientIp);
  if (ipOnlyState.attempts > 0) {
    await redis.del(`auth:ratelimit:${clientIp}`);
  }

  await redis.del(`auth:ratelimit:${compositeIdentifier}`);

  return { success: true };
}

export async function authenticateBatch(
  credentials: Array<{ username: string; password: string }>,
  clientIp: string
): Promise<Array<{ username: string; success: boolean; error?: string }>> {
  const ipState = await getRateLimitState(clientIp);

  if (ipState.locked) {
    return credentials.map(c => ({
      username: c.username,
      success: false,
      error: 'IP temporarily locked'
    }));
  }

  const results: Array<{ username: string; success: boolean; error?: string }> = [];

  for (const cred of credentials) {
    const result = await authenticateUser(cred.username, cred.password, clientIp);
    results.push({ username: cred.username, ...result });

    if (!result.success) {
      await recordFailedAttempt(clientIp);
    }
  }

  return results;
}
